-- Slice 7: 36 independently calculated fixed BigInt results, 12 bounds,
-- 11 invalid inputs, and 3 production metadata assertions = 62.
-- Expected values below were generated by a separate integer/factoradic model.
BEGIN;
CREATE TEMP TABLE stage02_stir_assertions(
    test_name text PRIMARY KEY,
    ok boolean NOT NULL CHECK(ok)
);
WITH fixtures(label,bowls,stir,expected) AS (VALUES
('ascending',ARRAY[1,2,3,4,5,6]::numeric[],1,ARRAY[43348,43821,49771,36114,57684,55801]::numeric[]),
('constant',ARRAY[7,7,7,7,7,7]::numeric[],12,ARRAY[3663739,3644624,3767824,3633179,3725243,3690584]::numeric[]),
('medium',ARRAY[1000,2000,3000,4000,5000,6000]::numeric[],6,ARRAY[4381178281,3014092096,2646911801,1613329216,3100755625,3161599056]::numeric[]),
('near-modulus',ARRAY[1,170141183460469231731687303715884105727,3,170141183460469231731687303715884105726,5,170141183460469231731687303715884105725]::numeric[],12,ARRAY[3452164,3426236,3250795,3359819,3326976,3283323]::numeric[]),
('wide',ARRAY[1298074214633706907132624082305025,1298074214633706907132624082305026,1298074214633706907132624082305027,1298074214633706907132624082305028,1298074214633706907132624082305029,1298074214633706907132624082305030]::numeric[],3,ARRAY[19603519087014954625182679103745284252,19040154877863925827487120252024889941,20897699079004760411593905313803427415,20196739003102558681742288309358695491,20876929891570621101079783328486546018,20721160985814576272223868438609938896]::numeric[]),
('descending',ARRAY[100,90,80,70,60,50]::numeric[],9,ARRAY[6262825,6892456,5361721,6176941,6795216,6012336]::numeric[])
), computed AS MATERIALIZED (
    SELECT label,expected,pastafari_sql_tamil.post_stir_round(bowls,stir) AS actual
    FROM fixtures
)
INSERT INTO stage02_stir_assertions(test_name,ok)
SELECT 'golden:'||label||':'||id,actual[id]=expected[id]
FROM computed CROSS JOIN generate_series(1,6) AS g(id);

WITH values_by_stir AS MATERIALIZED (
    SELECT stir,pastafari_sql_tamil.post_stir_round(
        ARRAY[1,2,3,4,5,6]::numeric[],stir) AS bowls
    FROM generate_series(1,12) AS g(stir)
)
INSERT INTO stage02_stir_assertions(test_name,ok)
SELECT 'bounds:'||stir,
    array_length(bowls,1)=6
    AND NOT EXISTS (
        SELECT 1 FROM unnest(bowls) AS x(v)
        WHERE v IS NULL OR v<1 OR v>pastafari_sql_tamil.save_modulus()
    )
FROM values_by_stir;

INSERT INTO stage02_stir_assertions(test_name,ok)
SELECT 'invalid:stir-zero',pastafari_sql_tamil.post_stir_round(ARRAY[1,2,3,4,5,6]::numeric[],0) IS NULL
UNION ALL
SELECT 'invalid:stir-thirteen',pastafari_sql_tamil.post_stir_round(ARRAY[1,2,3,4,5,6]::numeric[],13) IS NULL
UNION ALL
SELECT 'invalid:negative-stir',pastafari_sql_tamil.post_stir_round(ARRAY[1,2,3,4,5,6]::numeric[],-1) IS NULL
UNION ALL
SELECT 'invalid:short-bowls',pastafari_sql_tamil.post_stir_round(ARRAY[1,2]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:empty-bowls',pastafari_sql_tamil.post_stir_round(ARRAY[]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:null-member',pastafari_sql_tamil.post_stir_round(ARRAY[1,NULL,3,4,5,6]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:zero-member',pastafari_sql_tamil.post_stir_round(ARRAY[0,2,3,4,5,6]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:negative-member',pastafari_sql_tamil.post_stir_round(ARRAY[1,-2,3,4,5,6]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:fractional-member',pastafari_sql_tamil.post_stir_round(ARRAY[1.5,2,3,4,5,6]::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:null-bowls',pastafari_sql_tamil.post_stir_round(NULL::numeric[],1) IS NULL
UNION ALL
SELECT 'invalid:null-stir',pastafari_sql_tamil.post_stir_round(ARRAY[1,2,3,4,5,6]::numeric[],NULL::integer) IS NULL;

INSERT INTO stage02_stir_assertions(test_name,ok)
SELECT 'metadata:pure-production',
    (SELECT count(*)=0 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='pastafari_sql_tamil' AND p.proname='post_stir_round'
       AND position('pastafari_sql_tamil_test' IN pg_get_functiondef(p.oid))>0)
UNION ALL SELECT 'metadata:sql',
    (SELECT count(*)=1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     JOIN pg_language l ON l.oid=p.prolang
     WHERE n.nspname='pastafari_sql_tamil'
       AND p.proname='post_stir_round' AND l.lanname='sql')
UNION ALL SELECT 'metadata:immutable',
    (SELECT count(*)=1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='pastafari_sql_tamil'
       AND p.proname='post_stir_round' AND p.provolatile='i');

SELECT count(*) AS native_assertions FROM stage02_stir_assertions;
COMMIT;
